// 日本語 for the interface. How entries are matched is described at the top of i18n.js.
//
// To add a text: put the Chinese exactly as the page shows it (without a final 。) under "exact"; when it carries
// a value, under "patterns" with {x} (any text), {#n} (a number) or {@t} (a time) where the value stands.
// `python3 test/i18n_harvest.py` lists what the sources hold and no entry covers.
//
// Glossary — keep to it (です・ます体; katakana as Japanese VRChat players write it):
//   素材 アセット · 素材库 ライブラリ · 工程 プロジェクト · 流水线 パイプライン · 模型 アバター · 素体 素体
//   改模 アバター改変 · 衣服 衣装 · 头发 髪型 · 配饰 アクセサリー · 道具 小物 · 皮肤 スキン · 材质 マテリアル
//   表情 表情 · 光影 ライティング · 互动 インタラクション · 面捕 フェイストラッキング
//   插件 プラグイン (Unity) / パッケージ (VPM) · 装配 セットアップ · 菜单 メニュー · 开关 トグル · 互斥 排他
//   部件 パーツ · 配色 カラー · 装配方案 プリセット · 验收 確認 · 体检 チェック (アップロード前チェック)
//   同步参数 同期パラメータ · 位 ビット · 已购 購入済み / 購入品 · 网盘 ネットディスク · 百度网盘 Baidu Netdisk
//   分享 共有 · 提取码 抽出コード · 封面 サムネイル · 摄影棚 撮影スタジオ · 愿望单 ウィッシュリスト · 闲鱼 Xianyu
//   识图 画像認識 · 视觉模型 ビジョンモデル · 服务商 プロバイダー
//   Names stay as they are: Booth, Gumroad, Jinxxy, Modular Avatar, lilToon, ALCOM, VCC, UnitySkills, VRChat SDK.
