    // --- the AI service: providers, errors ---
    "在 platform.deepseek.com 申请 API Key。模型：deepseek-flash（支持识图）、deepseek-v4-pro（能力更强，不支持识图，截图时自动由 deepseek-flash 代为描述）。旧名称 deepseek-chat / deepseek-reasoner 已停用": "platform.deepseek.com で API Key を取得します。モデル：deepseek-flash（画像認識対応）、deepseek-v4-pro（高性能・画像認識非対応。スクリーンショットは deepseek-flash が自動で説明します）。旧名称の deepseek-chat / deepseek-reasoner は廃止されました",
    "在阿里云百炼（bailian.console.aliyun.com）申请 API Key。控制台提供的是带工作空间的地址（https://…maas.aliyuncs.com/compatible-mode/v1）时，请填写该地址。常用模型：qwen-plus、qwen-max、qwen3.8-max": "Alibaba Cloud 百煉（bailian.console.aliyun.com）で API Key を取得します。コンソールにワークスペース付きのアドレス（https://…maas.aliyuncs.com/compatible-mode/v1）が表示される場合は、そのアドレスを入力してください。主なモデル：qwen-plus、qwen-max、qwen3.8-max",
    "在智谱开放平台（bigmodel.cn）申请 API Key。常用模型：glm-5.3、glm-4.7；免费模型：glm-4.7-flash。识图使用其视觉模型（glm-4.6v-flash 免费）": "智譜オープンプラットフォーム（bigmodel.cn）で API Key を取得します。主なモデル：glm-5.3、glm-4.7。無料モデル：glm-4.7-flash。画像認識には同社のビジョンモデルを使用します（glm-4.6v-flash は無料）",
    "在 Kimi 开放平台（platform.kimi.com）申请 API Key。常用模型：kimi-k3、kimi-k2.6，均支持识图": "Kimi オープンプラットフォーム（platform.kimi.com）で API Key を取得します。主なモデル：kimi-k3、kimi-k2.6（いずれも画像認識対応）",
    "OpenAI 官方，或任何兼容 OpenAI 接口的服务（中转站、本地的 Ollama / LM Studio 等）：填写该服务提供的接口地址和 Key": "OpenAI 公式、または OpenAI 互換 API を持つ任意のサービス（中継サービス、ローカルの Ollama / LM Studio など）：そのサービスが提供するエンドポイントと Key を入力してください",
    "Anthropic 官方，或兼容 Anthropic 接口的服务：填写该服务提供的接口地址和 Key": "Anthropic 公式、または Anthropic 互換 API を持つサービス：そのサービスが提供するエンドポイントと Key を入力してください",
    "DeepSeek 的 deepseek-flash 支持识图": "DeepSeek の deepseek-flash は画像認識に対応しています",
    "glm-4.6v-flash 免费；能力更强的有 glm-4.6v、glm-5v-turbo": "glm-4.6v-flash は無料です。より高性能なものに glm-4.6v、glm-5v-turbo があります",
    "也可使用 qwen3.8-max 等自身支持识图的模型": "qwen3.8-max など、それ自体が画像認識に対応したモデルも使えます",
