    "在素材文件夹和下载位置中查找内容完全相同的文件：先比较大小，再比较文件片段，仅对仍然相同的文件读取全部内容。Unity 工程内的文件不参与比较": "アセットフォルダーとダウンロード先から、内容が完全に同じファイルを探します。まずサイズ、次にファイルの一部を比較し、それでも一致するファイルだけ全体を読み込みます。Unity プロジェクト内のファイルは比較対象外です",
