    "将素材库数据（素材列表、备注、标签、封面、已购和网盘记录等）导出为一个 zip 文件，在另一台电脑上导入。素材文件本身不包含在内，需自行复制": "ライブラリのデータ（アセット一覧、メモ、タグ、カバー、購入履歴、ネットディスクの記録など）を 1 つの zip ファイルにエクスポートし、別の PC でインポートします。アセットファイル自体は含まれないため、別途コピーしてください",
