    "unitypackage 内带有 Unity 生成的预览图（prefab 的渲染图、贴图的缩略图）。没有封面的素材会在每次扫描后自动从中提取封面；此处可立即为全部素材提取，并重试此前未找到预览图的素材": "unitypackage には Unity が生成したプレビュー画像（prefab のレンダリング、テクスチャの縮小画像）が含まれています。サムネイルのないアセットは、スキャンのたびに自動的にそこからサムネイルを抽出します。ここではすべてのアセットに対して今すぐ抽出でき、以前プレビュー画像が見つからなかったアセットも再試行します",
